#!/usr/bin/env bash
# Measures test coverage for this repo. Generated by the global /improve-coverage
# skill (scripts/init.py) for: gradle, node. Edited for this repo (see notes.md).
# This file belongs to the project: edit it freely (exclusions, extra flags,
# the project's own test script). The skill runs it and never regenerates it
# unless asked (init.py --force).
#
# Usage: bash .claude/coverage/measure.sh [--staged] [--live] [BLOCK...]
#   BLOCK...  run only these blocks
#   --staged  run only the blocks with a staged file (the pre-commit hook uses it)
#   --live    also run the live blocks (real test targets; never by default)
# Output: coverage-report/summary.txt (read this first), plus one HTML report
# per block in coverage-report/<block>/. Exit 1 when a test fails or a block is
# under its floor (FLOOR_LINES / FLOOR_BRANCHES below, or per block: the 4th
# and 5th argument of `floor`) or over its time budget in a full run. Write each changed floor and its reason in notes.md.
set -euo pipefail

# A generated script runs every test it finds, including tests that touch real
# accounts, money or devices. It refuses to run until someone has checked the
# exclusions (skill step 0.2) and set this to yes.
REVIEWED=yes
if [[ "$REVIEWED" != yes ]]; then
  echo "measure.sh is not reviewed: exclude tests that touch real systems, then set REVIEWED=yes" >&2
  exit 2
fi

# pwd -W (Git Bash on Windows) gives C:/... paths: Windows tools such as
# reportgenerator do not understand /c/... in their file patterns.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && { pwd -W 2>/dev/null || pwd; })"
OUT="$ROOT/coverage-report"
FLOOR_LINES=85
FLOOR_BRANCHES=75
# Time budget per block, in seconds: over it, a full run FAILS and the
# pre-commit hook only warns. A block may have its own (6th and 7th argument of
# `floor`: hook, full); write each one, with the reason, in notes.md.
BUDGET_HOOK=60
BUDGET_FULL=300
# Blocks that stay out of the hook run (--staged) because they are too slow and
# cannot be fixed yet. Space-separated names; the reason goes in notes.md ("Slow
# blocks"). A block here still runs in every full run.
# app: the emulator layers (integration, E2E) need a running emulator and
# about a minute more; the hook runs the JVM unit layer instead (app-unit).
HOOK_OFF="app"
SKILL="${IMPROVE_COVERAGE_HOME:-$HOME/.claude/skills/improve-coverage}"
PY="$(command -v python || command -v python3)"
LIVE=0; STAGED=0; ONLY=()
for a in "$@"; do
  case "$a" in --live) LIVE=1 ;; --staged) STAGED=1 ;; *) ONLY+=("$a") ;; esac
done
# --staged writes to its own folder, so a commit keeps the last full report.
(( STAGED )) && OUT="$OUT/staged"
SUMMARY="$OUT/summary.txt"
cd "$ROOT"
STAGED_FILES=()
(( STAGED )) && mapfile -t STAGED_FILES < <(git diff --cached --name-only)
rm -rf "$OUT"
mkdir -p "$OUT"
: > "$SUMMARY"
RESULTS="$OUT/floor.tsv"

# run NAME DIR...: run this block? (named on the command line, or with --staged:
# a staged file is under one of its folders). Starts the block's clock.
BLOCK_START=$SECONDS
run() {
  local name=$1 f d; shift
  if (( ${#ONLY[@]} )) && [[ " ${ONLY[*]} " != *" $name "* ]]; then return 1; fi
  if (( STAGED )) && [[ " $HOOK_OFF " == *" $name "* ]]; then
    echo "== $name: skipped in the hook (HOOK_OFF); a full run measures it" >&2
    return 1
  fi
  if (( ! STAGED )); then BLOCK_START=$SECONDS; return 0; fi
  for f in "${STAGED_FILES[@]}"; do
    for d in "$@"; do [[ "$d" == . || "$f" == "$d"/* ]] && { BLOCK_START=$SECONDS; return 0; }; done
  done
  return 1
}
# live NAME DIR...: like run, but only with --live
live() { (( LIVE )) && run "$@"; }
# floor NAME FORMAT FILE [LINES BRANCHES HOOK_S FULL_S]: check the block's report
# against the floor and its time (since `run`) against the budget
floor() {
  local mode=full budget=${7:-$BUDGET_FULL}
  (( STAGED )) && { mode=hook; budget=${6:-$BUDGET_HOOK}; }
  "$PY" "$SKILL/scripts/floor.py" check "$1" "$2" "$3" --lines "${4:-$FLOOR_LINES}" \
    --branches "${5:-$FLOOR_BRANCHES}" --seconds $(( SECONDS - BLOCK_START )) --budget "$budget" \
    --mode "$mode" --results "$RESULTS"
}
# slowest KIND FILE: the slowest test classes of a block (kind: trx, pytest, node)
slowest() { "$PY" "$SKILL/scripts/slowest.py" "$1" "$2" -n 3; }

# Android needs a JDK: Android Studio's bundled JBR, unless JAVA_HOME is set.
: "${JAVA_HOME:=C:/Program Files/Android/Android Studio/jbr}"
export JAVA_HOME

# --- app-unit: Gradle JVM unit layer, hook only ---
# The hook cannot start the emulator in time, so it runs only the plain-JVM
# tests. Their coverage alone (about 10 %) says nothing: no floor, the tests
# must pass and stay within the time budget.
if (( STAGED )) && run "app-unit" "app"; then
  echo "== app-unit (Gradle, JVM tests)"
  ( cd app && ./gradlew :app:testDebugUnitTest -q ) | tee "$OUT/app-unit.txt"
  { echo "## app-unit"; echo "JVM unit tests passed (no floor: see notes.md)"; echo; } >> "$SUMMARY"
fi

# --- app: all three layers on the emulator Frame (full runs only) ---
# scripts/run-all-tests.sh starts the emulator headless when none is attached
# and disconnects network ADB first: it never runs on the real frame. Floor on
# the merged JaCoCo report of the unit, integration and E2E layers.
if run "app" "app"; then
  echo "== app (Gradle, unit + integration + E2E on the emulator)"
  scripts/run-all-tests.sh | tee "$OUT/app.txt"
  { echo "## app"; grep -E "^(layer|coverage|total)" "$OUT/app.txt"; echo "(HTML: app/app/build/reports/jacoco/jacocoMergedReport/html/)"; echo; } >> "$SUMMARY"
  floor "app" jacoco "app/app/build/reports/jacoco/jacocoMergedReport/jacocoMergedReport.xml"
fi

# c8 replaces its default excludes when --exclude is given: list them all.
C8_EXCLUDES=(--exclude 'test/**' --exclude '**/*.test.js' --exclude 'gate-fixture.js' --exclude 'tmp/**' --exclude 'webcam-cache/**' --exclude 'photos/**')

# --- pi-video-gate: Node (c8 + node --test) ---
if run "pi-video-gate" "pi-video-gate"; then
  echo "== pi-video-gate (Node)"
  ( cd "pi-video-gate"
    npx --yes c8 --all "${C8_EXCLUDES[@]}" --reporter=text --reporter=html --reporter=json-summary --reports-dir="$OUT/pi-video-gate" node --test ) | tee "$OUT/pi-video-gate.txt"
  { echo "## pi-video-gate"; grep -E "^(Statements|Branches|Functions|Lines|All files|-+\||File )" "$OUT/pi-video-gate.txt" || tail -20 "$OUT/pi-video-gate.txt"; echo; } >> "$SUMMARY"
  floor "pi-video-gate" istanbul "$OUT/pi-video-gate/coverage-summary.json"
fi

# --- server: Node (c8 + node --test), the reference admin server ---
if run "server" "server"; then
  echo "== server (Node)"
  ( cd "server"
    npx --yes c8 --all "${C8_EXCLUDES[@]}" --reporter=text --reporter=html --reporter=json-summary --reports-dir="$OUT/server" node --test ) | tee "$OUT/server.txt"
  { echo "## server"; grep -E "^(Statements|Branches|Functions|Lines|All files|-+\||File )" "$OUT/server.txt" || tail -20 "$OUT/server.txt"; echo; } >> "$SUMMARY"
  floor "server" istanbul "$OUT/server/coverage-summary.json"
fi

# --- frame-scripts: Node (node --test) stub tests of the frame's shell scripts ---
# Bash has no line coverage here, so there is no floor: the block must pass and
# stay in time. The tests run the scripts under bash with stub commands.
if run "frame-scripts" "scripts"; then
  echo "== frame-scripts (Node, no coverage)"
  ( cd scripts && node --test test/ ) | tee "$OUT/frame-scripts.txt" | grep -E "^(ℹ (tests|pass|fail))|✖" || true
  if ! grep -q "^ℹ fail 0" "$OUT/frame-scripts.txt"; then echo "FAILED: frame-scripts" >&2; exit 1; fi
  { echo "## frame-scripts"; grep -E "^ℹ (tests|pass|fail)" "$OUT/frame-scripts.txt"; echo; } >> "$SUMMARY"
fi

echo
echo "=== summary ($SUMMARY) ==="
cat "$SUMMARY"
echo
echo "=== floor (default: lines $FLOOR_LINES %, branches $FLOOR_BRANCHES %) ==="
SKIPS="$ROOT/.claude/coverage/skips.log"
if [[ -s "$SKIPS" ]]; then
  echo "Commits that skipped the coverage hook (SKIP_COVERAGE=1):"
  cat "$SKIPS"
fi
"$PY" "$SKILL/scripts/floor.py" report "$RESULTS"
if (( ${#ONLY[@]} == 0 && STAGED == 0 )) && [[ -s "$SKIPS" ]]; then
  rm -f "$SKIPS"
  echo "skips.log cleared: a full run passes the floor"
fi
